function toApiHome(property){const price=property.price;const amount=price==null?'Price on request':`R ${Number(price).toLocaleString('en-ZA')}${(property.deal==='Rent out'||property.deal==='Rent')?' / month':''}`;return{id:`api-${property.id}`,type:property.type,deal:property.deal==='Rent out'||property.deal==='Rent'?'Rent':'Buy',price,priceText:amount,address:property.address,area:property.area,beds:property.beds??null,baths:property.baths??null,parking:property.parking??null,size:property.floorArea?`${property.floorArea} m²`:'Specs on request',features:Array.isArray(property.features)?property.features:[],tag:'NEW LISTING',images:property.photos||[],image:property.photos?.[0]||'',description:property.description}}
async function copyShareText(text){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(text);return}const field=document.createElement('textarea');field.value=text;field.setAttribute('readonly','');field.style.position='fixed';field.style.opacity='0';document.body.appendChild(field);field.select();const copied=document.execCommand('copy');field.remove();if(!copied)throw new Error('Clipboard unavailable')}
